/**
 * particleCatalog.ts
 *
 * The particles students build, predict and combine: leptons, gauge bosons,
 * light and heavy mesons, and the baryon octet and decuplet, with their
 * antiparticles generated by charge conjugation.
 *
 * Masses (MeV/c²) and mean lifetimes (s) are PDG 2024 values, rounded.
 * Seeded from RelativisticDynamics' PARTICLES table
 * (OpenLyceum/RelativisticDynamics src/common/model/particles.ts).
 */

import { contentKey, parseContent } from "./quarks.js";

export const FAMILIES = ["lepton", "boson", "meson", "baryon"] as const;
export type Family = (typeof FAMILIES)[number];

export type Particle = {
  /** Stable identifier, e.g. "p", "anti-p", "K+". Also the i18n name key's base. */
  readonly id: string;
  /** Display symbol (Unicode, not translated). */
  readonly symbol: string;
  /** Key into the particle-name strings (shared by a particle and its antiparticle). */
  readonly nameKey: string;
  readonly isAntiparticle: boolean;
  readonly family: Family;
  /** Electric charge, units of e. */
  readonly charge: number;
  readonly baryonNumber: number;
  readonly electronNumber: number;
  readonly muonNumber: number;
  readonly tauNumber: number;
  readonly strangeness: number;
  readonly charm: number;
  readonly beauty: number;
  /** Rest mass, MeV/c². */
  readonly mass: number;
  /** Spin in units of ħ/2 (1 = spin ½). */
  readonly spin2: number;
  /**
   * Quark content as compact strings (lowercase quark, uppercase antiquark).
   * Neutral flavourless mesons are mixtures, so they list every component:
   * π⁰ is ["uU", "dD"].
   */
  readonly contents: readonly string[];
  /** Mean lifetime, seconds; null for stable particles. */
  readonly lifetime: number | null;
  /** Id of the antiparticle (itself when self-conjugate). */
  readonly antiId: string;
};

type Spec = {
  id: string;
  symbol: string;
  anti?: string; // antiparticle symbol; omitted when self-conjugate
  nameKey?: string;
  family: Family;
  charge: number;
  mass: number;
  spin2: number;
  lifetime: number | null;
  contents?: string[];
  baryon?: number;
  le?: number;
  lmu?: number;
  ltau?: number;
  strange?: number;
  charm?: number;
  beauty?: number;
};

