function conjugateContent(content: string): string {
  return [...content].map((ch) => (ch === ch.toLowerCase() ? ch.toUpperCase() : ch.toLowerCase())).join("");
}

function antiId(id: string): string {
  return `anti-${id}`;
}

function build(spec: Spec, anti: boolean): Particle {
  const sign = anti ? -1 : 1;
  const selfConjugate = spec.anti === undefined;
  // Avoid −0 for antiparticles of neutral quantities.
  const signed = (value: number | undefined): number => (value ? sign * value : 0);
  return {
    id: anti ? antiId(spec.id) : spec.id,
    symbol: anti ? (spec.anti ?? spec.symbol) : spec.symbol,
    nameKey: spec.nameKey ?? spec.id,
    isAntiparticle: anti,
    family: spec.family,
    charge: signed(spec.charge),
    baryonNumber: signed(spec.baryon),
    electronNumber: signed(spec.le),
    muonNumber: signed(spec.lmu),
    tauNumber: signed(spec.ltau),
    strangeness: signed(spec.strange),
    charm: signed(spec.charm),
    beauty: signed(spec.beauty),
    mass: spec.mass,
    spin2: spec.spin2,
    contents: (spec.contents ?? []).map((c) => (anti ? conjugateContent(c) : c)),
    lifetime: spec.lifetime,
    antiId: selfConjugate ? spec.id : anti ? spec.id : antiId(spec.id),
  };
}

/** Every particle and antiparticle, particles first. */
export const PARTICLES: readonly Particle[] = [
  ...SPECS.map((spec) => build(spec, false)),
  ...SPECS.filter((spec) => spec.anti !== undefined).map((spec) => build(spec, true)),
];

const BY_ID = new Map(PARTICLES.map((p) => [p.id, p]));

export function particleById(id: string): Particle {
  const particle = BY_ID.get(id);
  if (!particle) {
    throw new Error(`particleById: unknown particle ${id}`);
  }
  return particle;
}

/**
 * Hadrons whose quark content matches `key` (see contentKey) and, when given,
 * whose spin matches. uds alone is ambiguous (Λ⁰, Σ⁰, Σ*⁰); spin narrows it.
 */
export function hadronsWithContent(key: string, spin2?: number): Particle[] {
  return PARTICLES.filter(
    (p) =>
      (spin2 === undefined || p.spin2 === spin2) &&
      p.contents.some((content) => contentKey(parseContent(content)) === key),
  );
}
